# Tighter bbox around Chinnathamandrapalli / Veppanapalli / EBTL (~12.6N 78.1E; village ~20km N of Krishnagiri)
# Also fetch Research Grade only and place-level Krishnagiri
python3 << 'PY'
import json, urllib.request
from collections import Counter

def fetch(url):
    with urllib.request.urlopen(url, timeout=60) as r:
        return json.load(r)

# place id 100698
d = fetch("https://api.inaturalist.org/v1/observations?place_id=100698&taxon_id=47119&per_page=200&order_by=observed_on")
print('PLACE Krishnagiri total', d.get('total_results'))
c=Counter(); rg=Counter()
for r in d.get('results',[]):
    t=r.get('taxon') or {}
    name=t.get('name') or '?'
    c[name]+=1
    if r.get('quality_grade')=='research':
        rg[name]+=1
print('Top all:')
for k,v in c.most_common(25): print(v,k)
print('Top RG:')
for k,v in rg.most_common(25): print(v,k)

print('\n--- TIGHT bbox CT Palli ---')
# ~12.50-12.70 N, 78.00-78.25 E
d2=fetch("https://api.inaturalist.org/v1/observations?taxon_id=47119&nelat=12.70&nelng=78.25&swlat=12.50&swlng=78.00&per_page=200")
print('total', d2.get('total_results'))
c2=Counter()
for r in d2.get('results',[]):
    t=r.get('taxon') or {}
    c2[t.get('name') or '?']+=1
    if c2[t.get('name') or '?']<=3:
        print(r.get('id'), t.get('name'), r.get('quality_grade'), r.get('location'), r.get('place_guess','')[:60])
print('species counts:')
for k,v in c2.most_common(30): print(v,k)
PY

